## Secure Implementation

### Tier 1: Critical Fix (5 min)

**Replace crypto-js with Node.js built-in crypto and proper bcrypt**

```javascript
const express = require('express');
const bcrypt = require('bcrypt'); // Industry-standard password hashing
const app = express();
app.use(express.json());

const users = new Map();
const BCRYPT_ROUNDS = 12; // 2^12 = 4,096 iterations (adjustable)

app.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'missing fields' });
  }

  if (users.has(email)) {
    return res.status(409).json({ error: 'user exists' });
  }

  try {
    // ✅ SECURE: bcrypt with salt and proper iterations
    const passwordHash = await bcrypt.hash(password, BCRYPT_ROUNDS);

    users.set(email, {
      email,
      passwordHash,
      algorithm: 'bcrypt',
      rounds: BCRYPT_ROUNDS,
      created: new Date().toISOString()
    });

    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: 'signup failed' });
  }
});

app.post('/login', async (req, res) => {
  const { email, password } = req.body;
  const user = users.get(email);

  if (!user) {
    return res.status(401).json({ error: 'invalid credentials' });
  }

  try {
    // ✅ SECURE: bcrypt.compare uses constant-time comparison
    const isValid = await bcrypt.compare(password, user.passwordHash);

    if (!isValid) {
      return res.status(401).json({ error: 'invalid credentials' });
    }

    res.json({ ok: true, user: email });
  } catch (err) {
    res.status(401).json({ error: 'authentication failed' });
  }
});

app.listen(3000);
```

### Tier 2: Essential Defenses (15 min)

**Add validation, rate limiting, and account lockout**

```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const app = express();
app.use(express.json());

const users = new Map();
const loginAttempts = new Map(); // Track failed attempts
const BCRYPT_ROUNDS = 12;
const MAX_LOGIN_ATTEMPTS = 5;
const LOCKOUT_DURATION = 15 * 60 * 1000; // 15 minutes

// ✅ Rate limit signup endpoint
const signupLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 signups per IP
  message: { error: 'too many signup attempts' }
});

// ✅ Rate limit login endpoint
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // 10 login attempts per IP
  message: { error: 'too many login attempts' }
});

function validatePassword(password) {
  // ✅ Enforce password complexity
  if (password.length < 12) {
    return { valid: false, error: 'password must be at least 12 characters' };
  }
  if (!/[a-z]/.test(password)) {
    return { valid: false, error: 'password must contain lowercase letter' };
  }
  if (!/[A-Z]/.test(password)) {
    return { valid: false, error: 'password must contain uppercase letter' };
  }
  if (!/[0-9]/.test(password)) {
    return { valid: false, error: 'password must contain number' };
  }
  return { valid: true };
}

function isAccountLocked(email) {
  const attempts = loginAttempts.get(email);
  if (!attempts) return false;

  if (attempts.count >= MAX_LOGIN_ATTEMPTS) {
    const lockoutEnd = attempts.lastAttempt + LOCKOUT_DURATION;
    if (Date.now() < lockoutEnd) {
      return true;
    } else {
      // Lockout expired, reset
      loginAttempts.delete(email);
      return false;
    }
  }
  return false;
}

function recordFailedLogin(email) {
  const attempts = loginAttempts.get(email) || { count: 0, lastAttempt: 0 };
  attempts.count += 1;
  attempts.lastAttempt = Date.now();
  loginAttempts.set(email, attempts);
}

function resetFailedLogins(email) {
  loginAttempts.delete(email);
}

app.post('/signup', signupLimiter, async (req, res) => {
  const { email, password } = req.body;

  // ✅ Validate email format
  if (!email || !validator.isEmail(email)) {
    return res.status(400).json({ error: 'invalid email format' });
  }

  // ✅ Validate password strength
  const pwdCheck = validatePassword(password);
  if (!pwdCheck.valid) {
    return res.status(400).json({ error: pwdCheck.error });
  }

  if (users.has(email)) {
    return res.status(409).json({ error: 'user exists' });
  }

  try {
    const passwordHash = await bcrypt.hash(password, BCRYPT_ROUNDS);

    users.set(email, {
      email,
      passwordHash,
      algorithm: 'bcrypt',
      rounds: BCRYPT_ROUNDS,
      created: new Date().toISOString()
    });

    // ✅ Log security event (without sensitive data)
    console.log({
      event: 'user_signup',
      email: email,
      timestamp: new Date().toISOString(),
      ip: req.ip
    });

    res.json({ ok: true });
  } catch (err) {
    console.error({ event: 'signup_error', error: err.message });
    res.status(500).json({ error: 'signup failed' });
  }
});

app.post('/login', loginLimiter, async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'missing fields' });
  }

  // ✅ Check account lockout
  if (isAccountLocked(email)) {
    console.log({
      event: 'login_attempt_locked',
      email: email,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
    return res.status(429).json({ error: 'account temporarily locked' });
  }

  const user = users.get(email);

  if (!user) {
    // ✅ Constant-time response even for non-existent users
    await bcrypt.hash('dummy', BCRYPT_ROUNDS);
    recordFailedLogin(email);
    return res.status(401).json({ error: 'invalid credentials' });
  }

  try {
    const isValid = await bcrypt.compare(password, user.passwordHash);

    if (!isValid) {
      recordFailedLogin(email);
      console.log({
        event: 'login_failed',
        email: email,
        attempts: loginAttempts.get(email).count,
        ip: req.ip,
        timestamp: new Date().toISOString()
      });
      return res.status(401).json({ error: 'invalid credentials' });
    }

    // ✅ Success - reset failed attempts
    resetFailedLogins(email);

    console.log({
      event: 'login_success',
      email: email,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });

    res.json({ ok: true, user: email });
  } catch (err) {
    console.error({ event: 'login_error', error: err.message });
    res.status(401).json({ error: 'authentication failed' });
  }
});

app.listen(3000);
```

### Tier 3: Production Hardening (30 min)

**Add monitoring, testing, and security headers**

```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const helmet = require('helmet');
const promClient = require('prom-client');
const app = express();

// ✅ Security headers
app.use(helmet());
app.use(express.json({ limit: '1kb' })); // Limit body size

const users = new Map();
const loginAttempts = new Map();
const BCRYPT_ROUNDS = 12;
const MAX_LOGIN_ATTEMPTS = 5;
const LOCKOUT_DURATION = 15 * 60 * 1000;

// ✅ Prometheus metrics
const signupCounter = new promClient.Counter({
  name: 'auth_signup_total',
  help: 'Total signup attempts',
  labelNames: ['status']
});

const loginCounter = new promClient.Counter({
  name: 'auth_login_total',
  help: 'Total login attempts',
  labelNames: ['status']
});

const loginDuration = new promClient.Histogram({
  name: 'auth_login_duration_seconds',
  help: 'Login duration in seconds',
  buckets: [0.1, 0.5, 1, 2, 5]
});

const accountLockoutCounter = new promClient.Counter({
  name: 'auth_lockout_total',
  help: 'Total account lockouts'
});

// Metrics endpoint
app.get('/metrics', async (req, res) => {
  res.set('Content-Type', promClient.register.contentType);
  res.end(await promClient.register.metrics());
});

const signupLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'too many signup attempts' }
});

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: { error: 'too many login attempts' }
});

function validatePassword(password) {
  if (password.length < 12) {
    return { valid: false, error: 'password must be at least 12 characters' };
  }
  if (!/[a-z]/.test(password)) {
    return { valid: false, error: 'password must contain lowercase letter' };
  }
  if (!/[A-Z]/.test(password)) {
    return { valid: false, error: 'password must contain uppercase letter' };
  }
  if (!/[0-9]/.test(password)) {
    return { valid: false, error: 'password must contain number' };
  }
  if (!/[!@#$%^&*]/.test(password)) {
    return { valid: false, error: 'password must contain special character' };
  }
  return { valid: true };
}

function isAccountLocked(email) {
  const attempts = loginAttempts.get(email);
  if (!attempts) return false;

  if (attempts.count >= MAX_LOGIN_ATTEMPTS) {
    const lockoutEnd = attempts.lastAttempt + LOCKOUT_DURATION;
    if (Date.now() < lockoutEnd) {
      accountLockoutCounter.inc();
      return true;
    } else {
      loginAttempts.delete(email);
      return false;
    }
  }
  return false;
}

function recordFailedLogin(email) {
  const attempts = loginAttempts.get(email) || { count: 0, lastAttempt: 0 };
  attempts.count += 1;
  attempts.lastAttempt = Date.now();
  loginAttempts.set(email, attempts);
}

function resetFailedLogins(email) {
  loginAttempts.delete(email);
}

app.post('/signup', signupLimiter, async (req, res) => {
  const { email, password } = req.body;

  if (!email || !validator.isEmail(email)) {
    signupCounter.inc({ status: 'invalid_email' });
    return res.status(400).json({ error: 'invalid email format' });
  }

  const pwdCheck = validatePassword(password);
  if (!pwdCheck.valid) {
    signupCounter.inc({ status: 'weak_password' });
    return res.status(400).json({ error: pwdCheck.error });
  }

  if (users.has(email)) {
    signupCounter.inc({ status: 'duplicate' });
    return res.status(409).json({ error: 'user exists' });
  }

  try {
    const passwordHash = await bcrypt.hash(password, BCRYPT_ROUNDS);

    users.set(email, {
      email,
      passwordHash,
      algorithm: 'bcrypt',
      rounds: BCRYPT_ROUNDS,
      created: new Date().toISOString(),
      lastPasswordChange: new Date().toISOString()
    });

    signupCounter.inc({ status: 'success' });

    console.log({
      event: 'user_signup',
      email: email,
      timestamp: new Date().toISOString(),
      ip: req.ip
    });

    res.json({ ok: true });
  } catch (err) {
    signupCounter.inc({ status: 'error' });
    console.error({ event: 'signup_error', error: err.message });
    res.status(500).json({ error: 'signup failed' });
  }
});

app.post('/login', loginLimiter, async (req, res) => {  
  const end = loginDuration.startTimer();
  const { email, password } = req.body;

  if (!email || !password) {
    loginCounter.inc({ status: 'missing_fields' });
    end();
    return res.status(400).json({ error: 'missing fields' });
  }

  if (isAccountLocked(email)) {
    loginCounter.inc({ status: 'locked' });
    console.log({
      event: 'login_attempt_locked',
      email: email,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
    end();
    return res.status(429).json({ error: 'account temporarily locked' });
  }

  const user = users.get(email);

  if (!user) {
    await bcrypt.hash('dummy', BCRYPT_ROUNDS);
    recordFailedLogin(email);
    loginCounter.inc({ status: 'failed' });
    end();
    return res.status(401).json({ error: 'invalid credentials' });
  }

  try {
    const isValid = await bcrypt.compare(password, user.passwordHash);

    if (!isValid) {
      recordFailedLogin(email);
      loginCounter.inc({ status: 'failed' });
      console.log({
        event: 'login_failed',
        email: email,
        attempts: loginAttempts.get(email).count,
        ip: req.ip,
        timestamp: new Date().toISOString()
      });
      end();
      return res.status(401).json({ error: 'invalid credentials' });
    }

    resetFailedLogins(email);
    loginCounter.inc({ status: 'success' });

    console.log({
      event: 'login_success',
      email: email,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });

    end();
    res.json({ ok: true, user: email });
  } catch (err) {
    loginCounter.inc({ status: 'error' });
    console.error({ event: 'login_error', error: err.message });
    end();
    res.status(401).json({ error: 'authentication failed' });
  }
});

app.listen(3000, () => {
  console.log('Authentication service running on port 3000');
  console.log('Metrics available at /metrics');
});
```

### Complete Example with Tests

```javascript
// test/auth.test.js
const request = require('supertest');
const bcrypt = require('bcrypt');
const app = require('../app'); // Your Express app

describe('Authentication Security Tests', () => {

  test('rejects crypto-js for password hashing', () => {
    const code = require('fs').readFileSync('app.js', 'utf8');
    expect(code).not.toContain('crypto-js');
    expect(code).not.toContain('CryptoJS.PBKDF2');
  });

  test('uses bcrypt for password hashing', () => {
    const code = require('fs').readFileSync('app.js', 'utf8');
    expect(code).toContain('bcrypt');
  });

  test('enforces password complexity', async () => {
    const response = await request(app)
      .post('/signup')
      .send({ email: 'test@example.com', password: 'weak' });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('12 characters');
  });

  test('implements account lockout after failed attempts', async () => {
    const email = 'lockout@example.com';

    // Create user
    await request(app)
      .post('/signup')
      .send({ email, password: 'StrongP@ssw0rd123' });

    // 5 failed login attempts
    for (let i = 0; i < 5; i++) {
      await request(app)
        .post('/login')
        .send({ email, password: 'wrong' });
    }

    // 6th attempt should be locked
    const response = await request(app)
      .post('/login')
      .send({ email, password: 'StrongP@ssw0rd123' });

    expect(response.status).toBe(429);
    expect(response.body.error).toContain('locked');
  });

  test('uses constant-time comparison', async () => {
    // Timing attack resistance test
    const email = 'timing@example.com';

    await request(app)
      .post('/signup')
      .send({ email, password: 'StrongP@ssw0rd123' });

    const times = [];

    for (let i = 0; i < 100; i++) {
      const start = Date.now();
      await request(app)
        .post('/login')
        .send({ email, password: 'WrongPassword123!' });
      times.push(Date.now() - start);
    }

    const avg = times.reduce((a, b) => a + b) / times.length;
    const variance = times.reduce((sum, t) => sum + Math.pow(t - avg, 2), 0) / times.length;

    // Low variance indicates constant-time
    expect(variance).toBeLessThan(1000);
  });
});
```

